CREATE FUNCTION depot_label (code varchar(10)) RETURNS varchar(40)
DETERMINISTIC NO EXTERNAL ACTION
BEGIN
    RETURN 'Depot ' || code || '; ''' || UPPER(code) || '''';--
END;


