SET CURRENT SCHEMA = "PARCELS ";
SET CURRENT PATH = "SYSIBM","SYSFUN","SYSPROC","SYSIBMADM","SYSHADOOP","DB2INST1";
CREATE VIEW parcels_in_transit AS SELECT p.id, p.tracking_number, c.full_name
AS courier FROM parcels p JOIN deliveries d ON d.parcel_id = p.id LEFT
JOIN couriers c ON c.id = d.courier_id WHERE p.status = 'in_transit';





-------------------------------
-- DDL Statements for Triggers
-------------------------------


SET SYSIBM.NLS_STRING_UNITS = 'SYSTEM';
SET CURRENT SCHEMA = "PARCELS ";
SET CURRENT PATH = "SYSIBM","SYSFUN","SYSPROC","SYSIBMADM","SYSHADOOP","DB2INST1";
CREATE TRIGGER parcels_lower_status
NO CASCADE BEFORE INSERT ON parcels
REFERENCING NEW AS n
FOR EACH ROW
BEGIN
    -- statuses are lower case; 'IN_TRANSIT' is 'in_transit'
    SET n.status = LOWER(n.status);--
END
;


